pragma solidity ^0.8.35; contract Base {function f(address value) public pure virtual returns(address){return value;}} contract Derived is Base {function f(address value) public pure override returns(address){return value;} function f(uint256 value) public pure returns(uint256){return value+1;}}
contract StatefulDerived is Derived {
 address public nativeOwner;
 uint256 public nativeAmount;
 uint256 public writes;
 function set(address v) external returns(address) {nativeOwner=f(v);writes++;require(v!=address(0));return nativeOwner;}
 function set(uint256 v) external returns(uint256) {nativeAmount=f(v);writes++;return nativeAmount;}
}

